import { useState } from 'react';
import { Button, Drawer, Divider } from '@jinx-ui/react';

type NavKey = 'projects' | 'team' | 'settings' | 'logout';

interface NavigationDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const navItems: { key: NavKey; label: string }[] = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function NavigationDrawer({ onNavigate }: NavigationDrawerProps) {
  const [open, setOpen] = useState(false);

  const handleSelect = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button onClick={() => setOpen(true)}>Меню</Button>

      <Drawer
        open={open}
        onOpenChange={setOpen}
        side="left"
        aria-label="Навигация"
      >
        <nav
          className="jx-stack"
          style={{ gap: 'var(--jx-space-2)', padding: 'var(--jx-space-4)' }}
        >
          {navItems.map((item) => (
            <button
              key={item.key}
              type="button"
              className="jx-menu-item"
              onClick={() => handleSelect(item.key)}
            >
              {item.label}
            </button>
          ))}

          <Divider style={{ margin: 'var(--jx-space-2) 0' }} />

          <button
            type="button"
            className="jx-menu-item jx-menu-item--danger"
            onClick={() => handleSelect('logout')}
          >
            Выйти
          </button>
        </nav>
      </Drawer>
    </>
  );
}

